const browserlessItems = $input.all();
const sourceItems = $('Preparar URL Scrape').all();

function decodeBasic(s) {
  return String(s || '')
    .replace(/\\\//g, '/')
    .replace(/\u0025/g, '%')
    .replace(/\u0026/g, '&')
    .replace(/\u003d/g, '=')
    .replace(/\u002F/gi, '/')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#039;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&nbsp;/g, ' ');
}

function cleanText(s) {
  return decodeBasic(s)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function simpleHash(str) {
  str = String(str || '');
  let h1 = 0xdeadbeef;
  let h2 = 0x41c6ce57;

  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }

  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);

  return ((h2 >>> 0).toString(16) + (h1 >>> 0).toString(16)).slice(0, 24);
}

function normalizeUrl(u) {
  return decodeBasic(u)
    .replace(/\\u0026/g, '&')
    .replace(/\s+/g, '')
    .trim();
}

function scoreImage(url) {
  const u = String(url || '');
  let score = 0;

  if (/scontent|fbcdn/i.test(u)) score += 5;
  if (/t39\.30808|safe_image|p960x960|p720x720|p1080x1080|_n\.(jpg|jpeg|png|webp)/i.test(u)) score += 4;
  if (/p50x50|p64x64|s75x75|s100x100|emoji|sprite|icon|logo|profile|static\.xx\.fbcdn\.net/i.test(u)) score -= 8;
  if (/\.jpg|\.jpeg|\.png|\.webp/i.test(u)) score += 2;
  if (u.length > 180) score += 1;

  return score;
}

function extractImage(htmlOrJson) {
  const h = decodeBasic(htmlOrJson);
  const candidates = [];

  const og = h.match(/<meta[^>]+(?:property|name)=["']og:image["'][^>]+content=["']([^"']+)["']/i);
  if (og?.[1]) candidates.push(og[1]);

  const imgRegex = /<img[^>]+>/gi;
  let m;

  while ((m = imgRegex.exec(h)) !== null) {
    const tag = m[0];

    const src =
      tag.match(/\ssrc=["']([^"']+)["']/i)?.[1] ||
      tag.match(/\sdata-src=["']([^"']+)["']/i)?.[1] ||
      tag.match(/\sdata-lazy-src=["']([^"']+)["']/i)?.[1] ||
      tag.match(/\sdata-original=["']([^"']+)["']/i)?.[1] ||
      '';

    if (src) candidates.push(src);

    const srcset = tag.match(/\ssrcset=["']([^"']+)["']/i)?.[1] || '';
    if (srcset) {
      for (const part of srcset.split(',')) {
        const candidate = part.trim().split(/\s+/)[0];
        if (candidate) candidates.push(candidate);
      }
    }
  }

  const bgRegex = /background-image\s*:\s*url\(([^)]+)\)/gi;
  while ((m = bgRegex.exec(h)) !== null) {
    candidates.push(m[1].replace(/^['"]|['"]$/g, ''));
  }

  // Facebook a veces mete las imágenes escapadas dentro de JSON/HTML.
  const urlRegex = /https?:\\?\/\\?\/[^"'<>\s)]+?(?:\.jpg|\.jpeg|\.png|\.webp)(?:\?[^"'<>\s)]*)?/gi;
  while ((m = urlRegex.exec(h)) !== null) {
    candidates.push(m[0]);
  }

  const cleaned = [...new Set(candidates.map(normalizeUrl))]
    .filter(Boolean)
    .filter(u => /^https?:\/\//i.test(u))
    .filter(u => !/emoji|sprite|static\.xx\.fbcdn\.net/i.test(u));

  cleaned.sort((a, b) => scoreImage(b) - scoreImage(a));
  return cleaned[0] || '';
}

function todayMadrid() {
  return new Date().toLocaleDateString('en-CA', {
    timeZone: 'Europe/Madrid',
  });
}

function firstResult(response) {
  return (
    response.data?.[0]?.results?.[0] ||
    response.data?.results?.[0] ||
    response.results?.[0] ||
    response[0]?.results?.[0] ||
    {}
  );
}

return browserlessItems.map((item, index) => {
  const source = sourceItems[index]?.json || {};
  const response = item.json || {};
  const result = firstResult(response);

  const fullJson = JSON.stringify(response);
  const rawText = result.text || response.text || response.data?.[0]?.text || '';
  const rawHtml = result.html || response.html || response.data?.[0]?.html || fullJson || '';

  let texto_limpio = cleanText(rawText || rawHtml)
    .replace(/Ver original · Califica esta traducción/gi, '')
    .replace(/Ver original/gi, '')
    .replace(/Califica esta traducción/gi, '')
    .replace(/See translation/gi, '')
    .replace(/Rate this translation/gi, '')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 8000);

  const imagen_url = extractImage(`${rawHtml}\n${fullJson}`);

  const textoBloqueado =
    /log in|email or phone|forgot password|create new account|allow the use of cookies|cookies from facebook|cookies from other companies|page insights data|privacy · terms|advertising · ad choices|join facebook or log in/i.test(texto_limpio);

  const tieneSenalesUtiles = Boolean(
    /prompt/i.test(texto_limpio) ||
    /chatgpt/i.test(texto_limpio) ||
    /midjourney/i.test(texto_limpio) ||
    /stable diffusion/i.test(texto_limpio) ||
    /dall[- ]?e/i.test(texto_limpio) ||
    /imagen|image|retrato|portrait|branding|logo|diseño|design|abrir chatgpt/i.test(texto_limpio) ||
    imagen_url
  );

  // Para páginas como Graphic Influence, aceptamos texto más corto si hay imagen o señales de prompt.
  const textoMinimo = imagen_url ? 35 : 80;

  const textoUtil = Boolean(
    texto_limpio.length >= textoMinimo &&
    !textoBloqueado &&
    tieneSenalesUtiles
  );

  const ultimo_hash = simpleHash(`${texto_limpio}|${imagen_url}`);
  const hashAnterior = String(source.ultimo_hash || '').trim();

  const hay_cambio = Boolean(
    textoUtil &&
    (!hashAnterior || hashAnterior !== ultimo_hash)
  );

  let scrape_motivo = 'OK';

  if (textoBloqueado) {
    scrape_motivo = 'Facebook muestra login/cookies/bloqueo';
  } else if (texto_limpio.length < textoMinimo) {
    scrape_motivo = 'Texto demasiado corto';
  } else if (!tieneSenalesUtiles) {
    scrape_motivo = 'No se detectó contenido útil';
  } else if (textoUtil && !hay_cambio) {
    scrape_motivo = 'Sin cambios desde última revisión';
  }

  return {
    json: {
      row_number: source.row_number,
      nombre: source.nombre,
      url: source.url,
      original_url: source.original_url || source.url,
      scrape_url: source.scrape_url || source.url,
      tipo: source.tipo,
      activo: source.activo,
      palabras_clave: source.palabras_clave,
      ultima_revision_anterior: source.ultima_revision || '',
      ultimo_hash_anterior: hashAnterior,
      estado_anterior: source.estado || '',
      motivo_anterior: source.motivo || '',

      texto_limpio,
      imagen_url,
      ultimo_hash,
      ultima_revision: todayMadrid(),

      scrape_ok: Boolean(textoUtil),
      hay_cambio: Boolean(hay_cambio),
      contenido_nuevo: Boolean(hay_cambio),
      scrape_status: textoUtil ? 'OK' : 'SIN_TEXTO_UTIL',
      scrape_motivo,
    },
  };
});

const j = $json;

const prompt_ia = `
Eres un analista de contenido para crear ideas de prompts de IA.

Analiza SOLO la información disponible. No inventes datos.

Cuenta: ${j.nombre}
URL: ${j.url}
Palabras clave esperadas: ${j.palabras_clave}

Texto scrapeado:
${j.texto_limpio}

Imagen detectada:
${j.imagen_url || 'No se detectó imagen'}

Devuelve la respuesta en Markdown con esta estructura:

# Análisis de ${j.nombre}

## Resumen
Resume qué se puede saber del contenido encontrado.

## Contenido útil detectado
Enumera temas, conceptos, estilos visuales o señales interesantes.

## Prompt principal
Si el texto incluye un prompt, extráelo y mejóralo ligeramente sin cambiar su intención.

## Ideas de prompts
Crea 5 prompts útiles basados en esta información.

## Recomendación
Di si merece la pena generar PDF: SÍ o NO, y por qué.
`.trim();

return {
  json: {
    ...j,
    prompt_ia,
  },
};

const ai = $json;
const base = $('Preparar prompt IA').item.json;

function getAiText(j) {
  if (typeof j === 'string') return j;
  return String(
    j.output?.text ||
    j.output ||
    j.text ||
    j.content ||
    j.message?.content ||
    j.message ||
    j.response?.content ||
    j.response ||
    j.result ||
    j.data ||
    ''
  );
}

const promptFinal = getAiText(ai).trim();

return {
  json: {
    fecha: base.ultima_revision,
    cuenta: base.nombre,
    texto: base.texto_limpio,
    prompt: promptFinal,
    imagen_url: base.imagen_url || '',
    post_url: base.url,
    categoria: base.palabras_clave,
    exportado_pdf: 'NO',
    ultimo_hash: base.ultimo_hash,
    url: base.url,
    ultima_revision: base.ultima_revision,
  },
};

let base = {};
try { base = $('Renombrar PDF').item.json; } catch (e) {}
if (!base.url) { try { base = $('Preparar HTML PDF').item.json; } catch (e) {} }
if (!base.url) { try { base = $('Preparar prompt IA').item.json; } catch (e) {} }

return {
  json: {
    url: base.url,
    nombre: base.nombre || base.cuenta,
    ultima_revision: base.ultima_revision || base.fecha,
    ultimo_hash: base.ultimo_hash,
    estado: 'OK',
    motivo: 'OK',
  },
};

const j = $json;

const sinCambios = Boolean(j.scrape_ok && !j.hay_cambio);

const estado = sinCambios
  ? 'SIN_CAMBIOS'
  : (j.scrape_status || 'SIN_TEXTO_UTIL');

const motivo = sinCambios
  ? 'Sin cambios desde última revisión'
  : (j.scrape_motivo || 'No se obtuvo texto útil');

return {
  json: {
    url: j.url,
    nombre: j.nombre,
    ultima_revision: j.ultima_revision,
    // Si fue fallo real, no guardamos el hash de una pantalla de login o error.
    // Si fue sin cambios, mantenemos el hash vigente.
    ultimo_hash: sinCambios ? (j.ultimo_hash || j.ultimo_hash_anterior || '') : (j.ultimo_hash_anterior || ''),
    estado,
    motivo,
  },
};

